<?php

namespace App\Modules\Inventory\Grpc\Proto;

use Grpc\BaseStub;
use Grpc\Channel;
use Grpc\UnaryCall;

/**
 * gRPC client for inventory.v1.InventoryService (proto/inventory/v1/inventory.proto).
 *
 * Written by hand in the shape grpc_php_plugin generates: one method per rpc,
 * each naming the remote method and the response class to decode into. The
 * message classes next to it are generated by protoc.
 */
class InventoryServiceClient extends BaseStub
{
    /**
     * @param  array<string, mixed>  $opts  must contain 'credentials'
     */
    public function __construct(string $hostname, array $opts, ?Channel $channel = null)
    {
        parent::__construct($hostname, $opts, $channel);
    }

    /**
     * @param  array<string, list<string>>  $metadata
     * @param  array<string, mixed>  $options  e.g. ['timeout' => microseconds]
     */
    public function GetStock(GetStockRequest $argument, array $metadata = [], array $options = []): UnaryCall
    {
        return $this->_simpleRequest(
            '/inventory.v1.InventoryService/GetStock',
            $argument,
            [GetStockResponse::class, 'decode'],
            $metadata,
            $options,
        );
    }

    /**
     * @param  array<string, list<string>>  $metadata
     * @param  array<string, mixed>  $options
     */
    public function Reserve(ReserveRequest $argument, array $metadata = [], array $options = []): UnaryCall
    {
        return $this->_simpleRequest(
            '/inventory.v1.InventoryService/Reserve',
            $argument,
            [ReserveResponse::class, 'decode'],
            $metadata,
            $options,
        );
    }

    /**
     * @param  array<string, list<string>>  $metadata
     * @param  array<string, mixed>  $options
     */
    public function Release(ReleaseRequest $argument, array $metadata = [], array $options = []): UnaryCall
    {
        return $this->_simpleRequest(
            '/inventory.v1.InventoryService/Release',
            $argument,
            [ReleaseResponse::class, 'decode'],
            $metadata,
            $options,
        );
    }

    /**
     * @param  array<string, list<string>>  $metadata
     * @param  array<string, mixed>  $options
     */
    public function SetStock(SetStockRequest $argument, array $metadata = [], array $options = []): UnaryCall
    {
        return $this->_simpleRequest(
            '/inventory.v1.InventoryService/SetStock',
            $argument,
            [SetStockResponse::class, 'decode'],
            $metadata,
            $options,
        );
    }
}
